import React, { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  LinearProgress,
  Paper,
  Select,
  Typography,
} from '@mui/material';
import {
  POTIONS,
  armPowerBoost,
  getPotions,
  isPowerBoostArmed,
  type PotionId,
} from '../utils/potions';
import {
  EMERALD_XP,
  ITEMS,
  bagCapacity,
  bagTotal,
  getBagTier,
  getItems,
  nextBagTier,
  setBagTier,
  type ItemId,
} from '../utils/items';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';

// The Inventory Bag (§11.4, world-asset-inventory): one item home
// over the two existing stores — potions (glacer-potions, untouched)
// and items (glacer-items). Lives on Profile (where emeralds are
// spent, next to the collection they power up), in the battle
// setup behind the Bag button (same panel, fighter preselected),
// and in the Navidex Stage's Bag panel. The bag counts every
// item in both stores against the OWNED bag tier's capacity
// (utils/items.ts BAG_TIERS: Traveler 50 / Explorer 100 / Realm
// 200); bigger bags are bought below with battle points — the
// game's own points, never real money.
//
// ICON SHELF (Round 36.5, Eddie 2026-11-19 ~12:17 PT): the
// items stop being a tabbed list of rows — they render as
// ICONS on a clean, grid-less shelf, and tapping an icon opens
// that item's pop-up: its name, how many the player has, a Use
// button and a Close button. PRESENTATION ONLY: every Use
// keeps its existing effect, handler, store and context
// exactly — the Power Draught still arms through armPowerBoost
// for the next duel, emeralds still power up through
// spendEmeraldsOn, and the in-duel-only items (health/recharge
// potions, shields, crystals) still have no bag-side spend:
// their pop-ups say so in the words the old rows used, with
// the Use button present but disabled. Inventing a new spend
// for them here would change the game's effects, which this
// round does not do.
type ShelfItemId = PotionId | ItemId;

export const InventoryBagPanel: React.FC<{
  defaultNavitarId?: string;
  // Optional reaction hook (Navidex Stage, 2026-11-16): fired with
  // the navitar's name when an item is successfully used ON a
  // navitar (today: Power-Up Emeralds), so a surface showing that
  // navitar can answer with a glow pulse. Presentational only.
  onItemUsedOnNavitar?: (navitarName: string) => void;
  // Round 36.9 Part 6: 'stage-pop' renders the panel inside the
  // Navidex Stage's Bag drop-down — the same shelf, item pop-ups
  // and handlers, with the header and footer compressed to
  // single lines. 'full' (Profile, the duel) is the original.
  variant?: 'full' | 'stage-pop';
}> = ({ defaultNavitarId, onItemUsedOnNavitar, variant = 'full' }) => {
  const { navitars, spendEmeraldsOn, points, spendPoints } = useNavitarFightClub();
  const [selected, setSelected] = useState<ShelfItemId | null>(null);
  const [, setTick] = useState(0);
  const refresh = () => setTick(t => t + 1);
  const [powerTargetId, setPowerTargetId] = useState<string>(defaultNavitarId ?? '');
  const [powerCount, setPowerCount] = useState(1);
  const [powerMessage, setPowerMessage] = useState<string | null>(null);

  const potions = getPotions();
  const items = getItems();
  const total = bagTotal();
  const armed = isPowerBoostArmed();
  const tier = getBagTier();
  const capacity = bagCapacity();
  const nextTier = nextBagTier();
  const [bagMessage, setBagMessage] = useState<string | null>(null);

  const handleBuyBag = () => {
    if (!nextTier) return;
    if (!spendPoints(nextTier.price)) {
      setBagMessage(
        `Not enough points yet — the ${nextTier.name} costs ${nextTier.price} points and you have ${points}. Win duels to earn more.`
      );
      return;
    }
    setBagTier(nextTier.tier);
    setBagMessage(`🎒 ${nextTier.name} unlocked! Your bag now holds ${nextTier.capacity} items.`);
    refresh();
  };
  const targetId = powerTargetId || defaultNavitarId || navitars[0]?.id || '';
  const target = navitars.find(n => n.id === targetId);
  const maxSpend = Math.max(0, items.emeralds);
  const spendCount = Math.min(Math.max(1, powerCount), Math.max(1, maxSpend));

  const handlePowerUp = () => {
    if (!target) return;
    const result = spendEmeraldsOn(target.id, spendCount);
    if (result.granted) {
      onItemUsedOnNavitar?.(target.name);
      setPowerMessage(
        `+${result.xpAdded} XP to ${target.name} (${result.emeraldsLeft} emeralds left)` +
          (result.leveledUp
            ? ` — 🎉 LEVEL UP! Lv ${result.leveledUp.from} → Lv ${result.leveledUp.to}`
            : '')
      );
      setPowerCount(1);
    } else {
      setPowerMessage('Not enough emeralds for that power up.');
    }
    refresh();
  };

  // The shelf's six citizens, in the order the old tabs kept
  // them: the three potions, then emeralds, shields, crystals.
  const shelf: { id: ShelfItemId; emoji: string; name: string; count: number }[] = [
    ...(Object.keys(POTIONS) as PotionId[]).map(id => ({
      id: id as ShelfItemId,
      emoji: POTIONS[id].emoji,
      name: POTIONS[id].name,
      count: potions[id],
    })),
    {
      id: 'emeralds' as ShelfItemId,
      emoji: ITEMS.emeralds.emoji,
      name: ITEMS.emeralds.name,
      count: items.emeralds,
    },
    {
      id: 'shields' as ShelfItemId,
      emoji: ITEMS.shields.emoji,
      name: ITEMS.shields.name,
      count: items.shields,
    },
    {
      id: 'crystals' as ShelfItemId,
      emoji: ITEMS.crystals.emoji,
      name: ITEMS.crystals.name,
      count: items.crystals,
    },
  ];

  const selectedMeta = selected ? shelf.find(s => s.id === selected) : undefined;
  // The in-duel-only line for an item, in the words its old row
  // carried — or null when the item has a real bag-side Use.
  const inDuelOnlyLine = (id: ShelfItemId): string | null => {
    if (id === 'health' || id === 'recharge')
      return 'In-duel only — use it from the battle deck during a duel; there is no way to spend it here.';
    if (id === 'shields')
      return `${ITEMS.shields.blurb} In-duel only — raise it from the battle deck; there is no button to press here.`;
    if (id === 'crystals')
      return `${ITEMS.crystals.blurb} In-duel only — fire it from the battle deck; there is no button to press here.`;
    return null;
  };
  const selectedBlurb = !selected
    ? ''
    : selected === 'emeralds'
      ? ITEMS.emeralds.blurb
      : selected === 'shields' || selected === 'crystals'
        ? '' // their in-duel line below carries the blurb already
        : POTIONS[selected as PotionId].blurb;

  const Root = (variant === 'stage-pop' ? Box : Paper) as React.ElementType;
  return (
    <Root {...(variant === 'stage-pop' ? {} : { sx: { p: 2 } })}>
      {variant === 'stage-pop' ? (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', mb: 0.5 }}>
          <Typography variant="body2" sx={{ fontWeight: 700 }}>
            🎒 {tier.name} · {total}/{capacity}
            {nextTier
              ? ` — next: ${nextTier.name}, ${nextTier.price} pts`
              : ' — the biggest bag there is'}
          </Typography>
          {nextTier && (
            <Button
              size="small"
              variant="outlined"
              color="secondary"
              disabled={points < nextTier.price}
              onClick={handleBuyBag}
              sx={{ py: 0, minHeight: 24, fontSize: '0.72rem', textTransform: 'none' }}
            >
              {points < nextTier.price
                ? `Need ${nextTier.price} pts`
                : `Buy — ${nextTier.price} pts`}
            </Button>
          )}
        </Box>
      ) : (
        <>
          <Typography variant="h6" gutterBottom>
            🎒 {tier.name} — {total}/{capacity}
          </Typography>
          <LinearProgress
            variant="determinate"
            value={capacity > 0 ? Math.min(100, (total / capacity) * 100) : 0}
            sx={{ mb: 1, height: 8, borderRadius: 4 }}
          />
        </>
      )}
      {total >= capacity && (
        <Typography variant="body2" color="warning.main" sx={{ mb: 1 }}>
          Bag full — spend or use some items, or get a bigger bag
          {variant === 'stage-pop' ? '.' : ' below.'}
        </Typography>
      )}
      {/* THE SHELF: icons only, no list, no boxes, no tabs.
          Each icon carries its count as a badge; an item the
          player has none of still shows, dimmed. */}
      <Box data-testid="bag-shelf" sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, py: 1 }}>
        {shelf.map(item => (
          <Button
            key={item.id}
            data-bag-item={item.id}
            aria-label={`${item.name} — you have ${item.count}`}
            onClick={() => {
              setSelected(item.id);
              setPowerMessage(null);
            }}
            sx={{
              position: 'relative',
              minWidth: 64,
              width: 64,
              height: 64,
              borderRadius: '50%',
              fontSize: '1.9rem',
              lineHeight: 1,
              opacity: item.count > 0 ? 1 : 0.45,
              bgcolor: 'rgba(120, 200, 225, 0.08)',
              '&:hover': { bgcolor: 'rgba(120, 200, 225, 0.2)' },
            }}
          >
            <span aria-hidden>{item.emoji}</span>
            <Box
              component="span"
              data-bag-count={item.id}
              sx={{
                position: 'absolute',
                right: -2,
                bottom: -2,
                minWidth: 22,
                height: 22,
                px: 0.5,
                borderRadius: 999,
                bgcolor: 'primary.main',
                color: 'primary.contrastText',
                fontSize: '0.72rem',
                fontWeight: 800,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                boxShadow: '0 2px 6px rgba(0,0,0,0.4)',
              }}
            >
              {item.count}
            </Box>
          </Button>
        ))}
      </Box>
      {/* THE ITEM POP-UP: name, the count as a number, the
          item's own context controls, Use, Close. */}
      <Dialog
        open={selected !== null}
        onClose={() => setSelected(null)}
        data-testid="bag-item-dialog"
        fullWidth
        maxWidth="xs"
      >
        {selectedMeta && selected && (
          <>
            <DialogTitle>
              {selectedMeta.emoji} {selectedMeta.name}
            </DialogTitle>
            <DialogContent>
              {selectedBlurb && (
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  {selectedBlurb}
                </Typography>
              )}
              <Typography variant="body1" gutterBottom>
                You have: <strong data-testid="bag-item-count">{selectedMeta.count}</strong>
              </Typography>
              {selected === 'power' && armed && (
                <Typography variant="body2" gutterBottom>
                  Armed for your next duel 🔥
                </Typography>
              )}
              {selected === 'emeralds' &&
                (navitars.length > 0 ? (
                  <Box
                    sx={{
                      display: 'flex',
                      gap: 1.5,
                      alignItems: 'center',
                      flexWrap: 'wrap',
                      mt: 1,
                    }}
                  >
                    <FormControl size="small" sx={{ minWidth: 180 }}>
                      <InputLabel id="bag-power-target-label">Power up</InputLabel>
                      <Select
                        labelId="bag-power-target-label"
                        label="Power up"
                        value={targetId}
                        onChange={e => setPowerTargetId(e.target.value)}
                      >
                        {navitars.map(n => (
                          <MenuItem key={n.id} value={n.id}>
                            {n.name} (Lv {n.level})
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={spendCount <= 1}
                        onClick={() => setPowerCount(c => Math.max(1, c - 1))}
                      >
                        −
                      </Button>
                      <Typography variant="body1" sx={{ minWidth: 28, textAlign: 'center' }}>
                        {spendCount}
                      </Typography>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={spendCount >= maxSpend}
                        onClick={() => setPowerCount(c => Math.min(maxSpend, c + 1))}
                      >
                        +
                      </Button>
                    </Box>
                  </Box>
                ) : (
                  <Typography variant="body2" color="text.secondary">
                    Create a navitar first — emeralds power up a navitar you own.
                  </Typography>
                ))}
              {selected === 'emeralds' && powerMessage && (
                <Typography variant="body2" sx={{ mt: 1 }}>
                  {powerMessage}
                </Typography>
              )}
              {inDuelOnlyLine(selected) && (
                <Typography variant="body2" color="text.secondary">
                  {inDuelOnlyLine(selected)}
                </Typography>
              )}
            </DialogContent>
            <DialogActions>
              <Button data-testid="bag-item-close" onClick={() => setSelected(null)}>
                Close
              </Button>
              {selected === 'power' ? (
                <Button
                  data-testid="bag-item-use"
                  variant="contained"
                  disabled={potions.power <= 0 || armed}
                  onClick={() => {
                    if (armPowerBoost()) refresh();
                  }}
                >
                  {armed ? 'Armed for next duel' : 'Arm for next duel'}
                </Button>
              ) : selected === 'emeralds' ? (
                <Button
                  data-testid="bag-item-use"
                  variant="contained"
                  disabled={maxSpend <= 0 || !target}
                  onClick={handlePowerUp}
                >
                  Power Up (+{EMERALD_XP * spendCount} XP)
                </Button>
              ) : (
                <Button data-testid="bag-item-use" variant="contained" disabled>
                  Use
                </Button>
              )}
            </DialogActions>
          </>
        )}
      </Dialog>
      {variant === 'stage-pop' ? (
        <>
          {bagMessage && (
            <Typography variant="body2" sx={{ mt: 1 }}>
              {bagMessage}
            </Typography>
          )}
          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
            Refill stations on the Realm Map top you up for free; win items in duels, earn a{' '}
            {ITEMS.emeralds.emoji} per venue check-in.
          </Typography>
        </>
      ) : (
        <>
          <Box
            sx={{ mt: 2, p: 1.5, border: '1px dashed', borderColor: 'divider', borderRadius: 2 }}
          >
            <Typography variant="subtitle2" gutterBottom>
              🎒 Get a bigger bag
            </Typography>
            {nextTier ? (
              <>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Next: <strong>{nextTier.name}</strong> — holds {nextTier.capacity} items (you
                  carry the {tier.name}, {capacity}). Costs {nextTier.price} battle points — your
                  balance: {points} points. Bigger bags are bought with points you win in duels,
                  never real money.
                </Typography>
                <Button
                  variant="contained"
                  color="secondary"
                  disabled={points < nextTier.price}
                  onClick={handleBuyBag}
                >
                  {points < nextTier.price
                    ? `Need ${nextTier.price} points — you have ${points}`
                    : `Buy the ${nextTier.name} — ${nextTier.price} points`}
                </Button>
              </>
            ) : (
              <Typography variant="body2" color="text.secondary">
                You carry the {tier.name} — the biggest bag there is ({capacity} items).
              </Typography>
            )}
            {bagMessage && (
              <Typography variant="body2" sx={{ mt: 1 }}>
                {bagMessage}
              </Typography>
            )}
          </Box>
          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
            Collect items at refill stations on the Realm Map, win them in duels, and earn a{' '}
            {ITEMS.emeralds.emoji} {ITEMS.emeralds.name} for each venue check-in (one per venue per
            day).
          </Typography>
        </>
      )}
    </Root>
  );
};

// Re-exported so surfaces that only need a count line don't reach
// into both stores themselves.
export const bagSummary = (): string => {
  const items = getItems();
  const potions = getPotions();
  const potionTotal = potions.health + potions.recharge + potions.power;
  return `${potionTotal} potions · ${items.emeralds}💎 · ${items.shields}🛡️ · ${items.crystals}🔮 — bag ${bagTotal()}/${bagCapacity()}`;
};

export type { ItemId };
