// Real-friends helpers for the multiplayer (Phase 1) features: profile
// lookup, friend requests, challenges, and starting a duel against a
// remote friend's navitar. Everything here fails gracefully — callers
// show a short inline error line, never a crash — when a table is
// missing or the network is down.
import {
  supabase,
  type BlockRow,
  type ChallengeRow,
  type FriendRow,
  type NavitarElement,
  type NavitarSnapshot,
  type ProfileRow,
} from './supabaseClient';
import { saveChallengeHandoff } from './challengeHandoff';

export type { ChallengeRow, FriendRow, NavitarSnapshot, ProfileRow };

// Build the stored snapshot from a local navitar (the fight-club user
// navitar shape). Only the display fields — hp / fastMove are derived
// from level at duel time, never stored.
export function navitarSnapshot(navitar: {
  name: string;
  element: NavitarElement;
  level: number;
  skills: string[];
  imageUrl?: string;
  modelUrl?: string;
  modelZoom?: number;
}): NavitarSnapshot {
  return {
    name: navitar.name,
    element: navitar.element,
    level: navitar.level,
    skills: navitar.skills,
    imageUrl: navitar.imageUrl,
    modelUrl: navitar.modelUrl,
    modelZoom: navitar.modelZoom,
  };
}

// Save (insert or update) a player's profile row: display name plus the
// current navitar snapshot, or null when they have no navitar yet. The
// landing funnel calls this when a signed-in player saves their profile
// or picks a navitar; Profile.tsx keeps its own inline upsert. Throws
// on error — callers show a short inline line, never a crash — so a
// missing profiles table fails gracefully. The upsert names only the
// display/snapshot columns, so it can never clobber a claimed @name
// (P2.0b): PostgREST writes only the columns it is given.
export async function upsertProfile(
  userId: string,
  displayName: string,
  snapshot: NavitarSnapshot | null
): Promise<void> {
  const { error } = await supabase.from('profiles').upsert({
    id: userId,
    display_name: displayName.trim() || null,
    navitar_name: snapshot?.name ?? null,
    navitar: snapshot,
  });
  if (error) throw error;
}

// Escape the LIKE wildcards in a typed handle fragment so a prefix
// search matches literally (an underscore in a @name is a character,
// not a single-char wildcard).
function escapeLikePattern(raw: string): string {
  return raw.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

// Look up profiles by @username (P2.0b): exact or prefix match on the
// handle — the add-by-username flow. Usernames are stored lowercase,
// and the typed query is normalized the same way, so the match is
// case-insensitive in effect. An exact match sorts first. The display
// name stays the shown label in results — it is just no longer the
// search key. Never returns the caller themselves, and never returns
// a profile that has not claimed a @name yet.
export async function searchProfilesByUsername(
  query: string,
  excludeUserId: string
): Promise<ProfileRow[]> {
  const handle = query.trim().replace(/^@+/, '').toLowerCase();
  if (!handle) return [];
  const { data, error } = await supabase
    .from('profiles')
    .select('id, display_name, username, is_owner, navitar_name, navitar, created_at')
    .ilike('username', `${escapeLikePattern(handle)}%`)
    .neq('id', excludeUserId)
    .order('username', { ascending: true })
    .limit(5);
  if (error) throw error;
  const rows = (data ?? []) as ProfileRow[];
  return rows.sort((a, b) => {
    const aExact = a.username === handle ? 0 : 1;
    const bExact = b.username === handle ? 0 : 1;
    return aExact - bExact;
  });
}

// Fetch profile rows for a list of user ids (one round trip). Empty in,
// empty out — no query is sent for an empty list.
export async function fetchProfilesByIds(ids: string[]): Promise<ProfileRow[]> {
  const unique = [...new Set(ids.filter(Boolean))];
  if (unique.length === 0) return [];
  const { data, error } = await supabase
    .from('profiles')
    .select('id, display_name, username, is_owner, navitar_name, navitar, created_at')
    .in('id', unique);
  if (error) throw error;
  return (data ?? []) as ProfileRow[];
}

// A friend row plus the OTHER side's profile (the person this row is
// about, from the caller's point of view).
export interface FriendEntry {
  row: FriendRow;
  otherId: string;
  profile: ProfileRow | null;
}

// A challenge row plus the OTHER side's profile.
export interface ChallengeEntry {
  row: ChallengeRow;
  otherId: string;
  profile: ProfileRow | null;
}

function attachProfiles<T>(
  rows: T[],
  profiles: ProfileRow[],
  otherOf: (row: T) => string
): { row: T; otherId: string; profile: ProfileRow | null }[] {
  const byId = new Map(profiles.map(p => [p.id, p]));
  return rows.map(row => {
    const otherId = otherOf(row);
    return { row, otherId, profile: byId.get(otherId) ?? null };
  });
}

// Incoming friend requests: rows where I am the friend and the request
// is still pending.
export async function fetchIncomingRequests(me: string): Promise<FriendEntry[]> {
  const { data, error } = await supabase
    .from('friends')
    .select('id, user_id, friend_id, status, created_at')
    .eq('friend_id', me)
    .eq('status', 'pending')
    .order('created_at', { ascending: true });
  if (error) throw error;
  const rows = (data ?? []) as FriendRow[];
  const profiles = await fetchProfilesByIds(rows.map(r => r.user_id));
  return attachProfiles(rows, profiles, r => r.user_id);
}

// Accepted friends: rows where I am either side and the status is
// accepted.
export async function fetchAcceptedFriends(me: string): Promise<FriendEntry[]> {
  const { data, error } = await supabase
    .from('friends')
    .select('id, user_id, friend_id, status, created_at')
    .eq('status', 'accepted')
    .or(`user_id.eq.${me},friend_id.eq.${me}`)
    .order('created_at', { ascending: true });
  if (error) throw error;
  const rows = (data ?? []) as FriendRow[];
  const profiles = await fetchProfilesByIds(
    rows.map(r => (r.user_id === me ? r.friend_id : r.user_id))
  );
  return attachProfiles(rows, profiles, r => (r.user_id === me ? r.friend_id : r.user_id));
}

// Incoming challenges: rows where I am the challenged player and the
// challenge is still pending.
export async function fetchIncomingChallenges(me: string): Promise<ChallengeEntry[]> {
  const { data, error } = await supabase
    .from('challenges')
    .select('id, from_user, to_user, from_navitar, status, created_at')
    .eq('to_user', me)
    .eq('status', 'pending')
    .order('created_at', { ascending: true });
  if (error) throw error;
  const rows = (data ?? []) as ChallengeRow[];
  const profiles = await fetchProfilesByIds(rows.map(r => r.from_user));
  return attachProfiles(rows, profiles, r => r.from_user);
}

// Challenges I sent that are still awaiting a reply — pending ones, plus
// ones the other side just accepted (the poll surface for "X accepted
// your challenge!").
export async function fetchSentChallenges(me: string): Promise<ChallengeEntry[]> {
  const { data, error } = await supabase
    .from('challenges')
    .select('id, from_user, to_user, from_navitar, status, created_at')
    .eq('from_user', me)
    .in('status', ['pending', 'accepted'])
    .order('created_at', { ascending: true });
  if (error) throw error;
  const rows = (data ?? []) as ChallengeRow[];
  const profiles = await fetchProfilesByIds(rows.map(r => r.to_user));
  return attachProfiles(rows, profiles, r => r.to_user);
}

// Send a friend request. Error codes the caller turns into plain
// lines (never raw database text):
// - 23505 (Paste #2's pair-unique index): the pair already has a row
//   in SOME direction — either my request is already out, or THEY
//   already asked me (the caller checks which and words it plainly).
// - 42501 (Paste #2's block guard trigger): a block exists between
//   the pair in one direction or the other. The caller shows a
//   neutral "couldn't be sent" line and NOTHING more — a blocked
//   player gets no signal that reveals the block (Eddie's law).
export async function sendFriendRequest(me: string, them: string): Promise<void> {
  const { error } = await supabase
    .from('friends')
    .insert({ user_id: me, friend_id: them, status: 'pending' });
  if (error) throw error;
}

// Accept an incoming friend request.
export async function acceptFriendRequest(rowId: string): Promise<void> {
  const { error } = await supabase.from('friends').update({ status: 'accepted' }).eq('id', rowId);
  if (error) throw error;
}

// Decline an incoming friend request — the row is deleted.
export async function declineFriendRequest(rowId: string): Promise<void> {
  const { error } = await supabase.from('friends').delete().eq('id', rowId);
  if (error) throw error;
}

// ---- Real block (P2.1, Paste #2's public.blocks) ----
// A block is the blocker's private control, never a record on the
// blocked person: RLS shows blocks rows to the blocker alone, and
// nothing anywhere in the app tells the blocked player it happened.
// Until Paste #2 lands, the table does not exist and every helper
// here throws (PGRST205) — Profile treats that as "blocking isn't
// live yet" and simply doesn't render the controls.

// The ids of everyone I have blocked.
export async function fetchBlockedIds(me: string): Promise<string[]> {
  const { data, error } = await supabase
    .from('blocks')
    .select('id, blocker_id, blocked_id, created_at')
    .eq('blocker_id', me)
    .order('created_at', { ascending: true });
  if (error) throw error;
  return ((data ?? []) as BlockRow[]).map(r => r.blocked_id);
}

// The people I have blocked, with their profiles — the management
// list behind the Blocked players section (unblock lives there).
export async function fetchBlockedProfiles(me: string): Promise<ProfileRow[]> {
  const ids = await fetchBlockedIds(me);
  return fetchProfilesByIds(ids);
}

// Block a player: write my blocks row, then sever whatever stands
// between us — any friend row in either direction (friendship or
// pending request) and any still-pending challenge in either
// direction. The severing deletes are best-effort (the block itself
// is the enforcement: Paste #2's guard trigger refuses any new
// request between a blocked pair at the database level), so a
// failed cleanup never un-does the block. Throws only when the
// block write itself fails.
export async function blockPlayer(me: string, them: string): Promise<void> {
  const { error } = await supabase.from('blocks').insert({ blocker_id: me, blocked_id: them });
  if (error) throw error;
  const sever = async (run: () => PromiseLike<{ error: unknown }>) => {
    try {
      await run();
    } catch {
      // Best effort: the block stands regardless.
    }
  };
  await sever(() => supabase.from('friends').delete().eq('user_id', me).eq('friend_id', them));
  await sever(() => supabase.from('friends').delete().eq('user_id', them).eq('friend_id', me));
  await sever(() =>
    supabase
      .from('challenges')
      .delete()
      .eq('from_user', me)
      .eq('to_user', them)
      .eq('status', 'pending')
  );
  await sever(() =>
    supabase
      .from('challenges')
      .delete()
      .eq('from_user', them)
      .eq('to_user', me)
      .eq('status', 'pending')
  );
}

// Unblock a player: remove my blocks row. This does NOT restore any
// friendship the block severed — it only lets requests flow again.
export async function unblockPlayer(me: string, them: string): Promise<void> {
  const { error } = await supabase
    .from('blocks')
    .delete()
    .eq('blocker_id', me)
    .eq('blocked_id', them);
  if (error) throw error;
}

// Start a duel against a real friend's navitar. The remote navitar
// becomes a fight-club opponent (explicit id `friend-<userId>`, so two
// friends' navitars can never collide the way name-slug ids could),
// the challenge handoff carries the pairing to the challenge screen
// (Round 10) — the player sees the matchup, can swap their fighter
// in place, and presses Battle there to start the duel, which then
// plays exactly like a demo duel — AI-driven opponent, points/XP
// banked locally as today.
//
// The caller supplies the fight-club + navigation functions; this
// helper stays a plain function so both accept flows (incoming
// challenge, sent challenge accepted) share the one path.
export interface FriendDuelDeps {
  addRemoteOpponent: (
    input: {
      name: string;
      element: NavitarElement;
      level: number;
      skills: string[];
      imageUrl?: string;
      modelUrl?: string;
      modelZoom?: number;
    },
    id: string
  ) => string;
  navigate: (path: string) => void;
}

export async function startFriendDuel(
  deps: FriendDuelDeps,
  friendUserId: string,
  snapshot: NavitarSnapshot,
  challengeId?: string,
  friendName?: string | null
): Promise<void> {
  const opponentInput = {
    name: snapshot.name,
    element: snapshot.element,
    level: snapshot.level,
    skills: snapshot.skills,
    imageUrl: snapshot.imageUrl,
    modelUrl: snapshot.modelUrl,
    modelZoom: snapshot.modelZoom,
  };
  const opponentId = deps.addRemoteOpponent(opponentInput, `friend-${friendUserId}`);
  if (!opponentId) {
    // The fighter can't be fielded as an opponent (a locked design) —
    // there is no matchup to show, so don't navigate anywhere.
    return;
  }
  // After a duel starts from an accepted challenge, mark that challenge
  // completed — best effort only. A failure here must never block the
  // duel, so it is swallowed. (Round 10 note: the mark now happens
  // when the player takes the duel up onto the challenge screen —
  // the same "accepted → duel initiated" moment the old flow marked
  // on the way to the Battle page.)
  if (challengeId) {
    try {
      await supabase.from('challenges').update({ status: 'completed' }).eq('id', challengeId);
    } catch {
      // Best effort: the duel still starts.
    }
  }
  saveChallengeHandoff({
    opponentId,
    opponent: opponentInput,
    kind: 'remote',
    personName: friendName ?? null,
    venueId: '',
    sourceLabel: 'Profile',
    returnTo: '/profile',
    demo: false,
    directStart: false,
    ts: Date.now(),
  });
  deps.navigate('/challenge');
}
