import React, { Suspense, lazy } from 'react';
import type { MessageModMenuProps, ParticipantsPanelProps } from './ModerationPanels';

// Lazy doors to the on-demand moderation surfaces (Slim Round S3,
// 2026-11-20). MessageModMenu and ParticipantsPanel live in
// ModerationPanels.tsx, which webpack splits into its own chunk —
// it loads the first time a player opens a chat space's moderation
// surface, and is cached after that. Each wrapper carries its own
// Suspense boundary with a null fallback, so call sites render
// exactly as before: while the chunk is in flight the ⋯ button /
// panel simply isn't there yet, and nothing else on the page moves.
// (The moderation state itself — utils/moderation.ts — is NOT lazy:
// message rendering reads it synchronously, as always.)

const MessageModMenuInner = lazy(() =>
  import('./ModerationPanels').then(m => ({ default: m.MessageModMenu }))
);
const ParticipantsPanelInner = lazy(() =>
  import('./ModerationPanels').then(m => ({ default: m.ParticipantsPanel }))
);

export const MessageModMenu: React.FC<MessageModMenuProps> = props => (
  <Suspense fallback={null}>
    <MessageModMenuInner {...props} />
  </Suspense>
);

export const ParticipantsPanel: React.FC<ParticipantsPanelProps> = props => (
  <Suspense fallback={null}>
    <ParticipantsPanelInner {...props} />
  </Suspense>
);
