import React, { useEffect, useRef, useState } from 'react';
import { Box, Typography } from '@mui/material';
import { elementColor, elementEmoji } from '../utils/navitarArt';

// Art image with a loading treatment: the image sits on an
// element-coloured gradient, so while it loads (or if it fails) the
// slot never reads as an empty circle or a flat-colour block — and it
// fades in on load instead of popping in. CSS only, no spinner.
// Used by the battle stage, the map's person thumbs, Profile, and the
// showcase cards.
//
// Two failure modes this guards against (both observed in the wild):
// 1. Cached-image race: an image already in the browser's cache can
//    finish loading before React attaches the onLoad handler, so
//    `loaded` stays false and the image sits invisible (opacity 0)
//    over the gradient forever — exactly the "flat colour blob, no art"
//    the browser check saw on Home while the identical art rendered
//    fine on Collection. The `complete` check on mount closes it: an
//    already-loaded image shows immediately.
// 2. A genuinely failed load: instead of an invisible box, the slot
//    shows the element emoji — always something visible.
//
// One more, seen on a phone: a transient load failure (slow or flaky
// network) fires onError once and leaves the emoji — the snowflake —
// in place of the navitar art, until the page is reloaded. So a failed
// load retries once after ~1s (fresh fetch, cache-busted) before the
// emoji fallback is shown.
export const NavitarArtImg: React.FC<{
  src: string;
  alt: string;
  element: string;
  style?: React.CSSProperties;
  // How the bitmap sits in its box. 'cover' (default) fills the box
  // and crops the overflow — right for small round thumbs and bust
  // shots. 'contain' shows the WHOLE creature: the Navidex cards
  // (Round 9, Eddie 2026-11-16: "the card pictures are zoomed too
  // close or cut off... some of the creatures don't have their full
  // wings") — portraits come in square, portrait and landscape, so
  // cover in the wide card box was shaving wings off. In contain
  // mode the bitmap letterboxes onto this component's element-tinted
  // gradient (already the box background), and the img gets a small
  // padding inset so the card idle animations (breathe scale ~1.03,
  // prowl shift ±7px in modern.css) can't push a wingtip past the
  // frame edge mid-animation.
  fit?: 'cover' | 'contain';
}> = ({ src, alt, element, style, fit = 'cover' }) => {
  const [loaded, setLoaded] = useState(false);
  const [failed, setFailed] = useState(false);
  const [attempt, setAttempt] = useState(0);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const color = elementColor(element);
  const effectiveSrc = attempt === 0 ? src : `${src}${src.includes('?') ? '&' : '?'}retry=1`;

  useEffect(() => {
    const img = imgRef.current;
    // A new src starts unloaded (unless it is already complete — the
    // cached-image case above). `complete` is also true for a broken
    // image, so naturalWidth has to be > 0 as well.
    setFailed(false);
    setAttempt(0);
    setLoaded(!!(img && img.complete && img.naturalWidth > 0));
  }, [src]);

  const handleError = () => {
    if (attempt === 0) {
      window.setTimeout(() => setAttempt(1), 1200);
    } else {
      setFailed(true);
    }
  };

  if (failed) {
    return (
      <Box
        sx={{
          position: 'relative',
          overflow: 'hidden',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '2rem',
          background: `radial-gradient(circle at 35% 30%, ${color}66, var(--glacer-art-tile-end, #121212) 75%)`,
          ...style,
        }}
        role="img"
        aria-label={alt}
      >
        {elementEmoji(element)}
      </Box>
    );
  }

  return (
    <Box
      sx={{
        position: 'relative',
        overflow: 'hidden',
        background: `radial-gradient(circle at 35% 30%, ${color}66, var(--glacer-art-tile-end, #121212) 75%)`,
        ...style,
      }}
    >
      <img
        ref={imgRef}
        src={effectiveSrc}
        alt={alt}
        // Load-speed trim (Stage Polish round, Item D): native
        // lazy loading + async decoding. On the Navidex the grid
        // mounts 116 cards at once; without this every card's art
        // fetched eagerly on arrival (~19MB of webp across the
        // fleet). In-view images still load immediately — lazy
        // only defers what's off-screen until the player scrolls
        // near it. Same picture, same fade-in, same fallbacks.
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={handleError}
        style={{
          width: '100%',
          height: '100%',
          objectFit: fit,
          display: 'block',
          opacity: loaded ? 1 : 0,
          transition: 'opacity 0.45s ease-in',
          ...(fit === 'contain' ? { padding: 10, boxSizing: 'border-box' as const } : {}),
        }}
      />
    </Box>
  );
};
