// Notification toasts (Round 17, Eddie 2026-11-17) — the pop-up
// face of the notifications store (utils/notifications.ts).
//
// Eddie's shape for it: a notification FLOATS IN AT A CORNER, you
// can tap it to go check the thing out, and if you don't it goes
// down fast on its own. It never sits in the middle of the screen
// and never interrupts the game. This component replaces the two
// top-CENTRE pills (venue + icebreaker, Round 3) — one system now:
// every producer writes to the store, and this stack is simply the
// store's freshest records, shown briefly.
//
// Discipline:
// - Top-right corner, under the top bar; a stack of at most 3.
// - Each toast auto-dismisses after ~5s. Dismissing a toast only
//   tucks the pop-up away — the record stays in the notifications
//   home, unread, until the player actually opens it. (The ✕ on a
//   venue toast keeps its old extra meaning — "not this notice
//   again today" — and an icebreaker's ✕ resolves the offer, both
//   exactly as the pills behaved.)
// - Pointer events: the stack container lets everything through;
//   only a toast card itself is tappable. During a battle the
//   D-pad (bottom of the screen) is nowhere near the corner, and
//   even a stray toast can only ever intercept its own rectangle.
import React, { useEffect } from 'react';
import { Box, IconButton, Paper, Typography } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { useNotifications } from '../contexts/NotificationsContext';
import { usePresence } from '../contexts/PresenceContext';
import { dismissVenueNoticeForDay } from '../data/venueBuzz';
import type { GlacerNotification, NotificationKind } from '../utils/notifications';

const KIND_EMOJI: Record<NotificationKind, string> = {
  venue: '📍',
  icebreaker: '💬',
  friend: '🤝',
  suggestion: '✨',
  message: '💬',
  event: '📅',
  fighter: '✔️',
};

const KIND_ACTION: Record<NotificationKind, string> = {
  venue: 'Tap to see it on the map',
  icebreaker: 'Tap to meet them',
  friend: 'Tap to view',
  suggestion: 'Tap to view',
  message: 'Tap to read it in your Inbox',
  event: 'Tap to see the event',
  fighter: 'Tap to view in the Navidex',
};

// How long a toast stays up before it tucks itself away (Eddie:
// "it'll go down really fast"). The record persists in the
// notifications home regardless.
const TOAST_MS = 5000;

const ToastCard: React.FC<{ notification: GlacerNotification }> = ({ notification }) => {
  const { activate, dismissToast } = useNotifications();
  const { dismissIcebreaker } = usePresence();

  useEffect(() => {
    const t = window.setTimeout(() => dismissToast(notification.id), TOAST_MS);
    return () => window.clearTimeout(t);
  }, [notification.id, dismissToast]);

  const close = (e: React.MouseEvent) => {
    e.stopPropagation();
    // Kind-specific "don't show me this again" semantics the old
    // pills carried — the record itself stays in the home either way.
    if (notification.kind === 'venue' && notification.sourceId) {
      dismissVenueNoticeForDay(notification.sourceId);
    }
    if (notification.kind === 'icebreaker') {
      dismissIcebreaker();
    }
    dismissToast(notification.id);
  };

  return (
    <Paper
      data-testid="notification-toast"
      data-kind={notification.kind}
      data-notification-id={notification.id}
      elevation={8}
      className="glacer-toast-pop"
      onClick={() => activate(notification)}
      sx={{
        pointerEvents: 'auto',
        width: 'min(330px, calc(100vw - 24px))',
        px: 1.5,
        py: 1,
        borderRadius: '16px',
        display: 'flex',
        alignItems: 'flex-start',
        gap: 1.25,
        cursor: 'pointer',
      }}
    >
      <Box
        sx={{
          width: 34,
          height: 34,
          borderRadius: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '1.05rem',
          flexShrink: 0,
          bgcolor: 'rgba(18, 165, 199, 0.15)',
        }}
      >
        {KIND_EMOJI[notification.kind]}
      </Box>
      <Box sx={{ flex: 1, minWidth: 0 }}>
        <Typography
          sx={{
            fontSize: '0.85rem',
            fontWeight: 700,
            lineHeight: 1.25,
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {notification.title}
        </Typography>
        <Typography
          variant="caption"
          color="text.secondary"
          sx={{
            display: 'block',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {notification.demo ? 'DEMO · ' : ''}
          {notification.body}
        </Typography>
        <Typography
          variant="caption"
          color="primary"
          sx={{ display: 'block', fontWeight: 700, mt: 0.25 }}
        >
          {KIND_ACTION[notification.kind]} →
        </Typography>
      </Box>
      <IconButton
        size="small"
        onClick={close}
        aria-label="Dismiss notification"
        data-testid="notification-toast-close"
        sx={{ flexShrink: 0, mt: -0.5, mr: -0.5 }}
      >
        <CloseIcon fontSize="small" />
      </IconButton>
    </Paper>
  );
};

const NotificationToasts: React.FC = () => {
  const { toasts } = useNotifications();
  const visible = toasts.slice(0, 3);
  if (visible.length === 0) return null;
  return (
    <Box
      data-testid="notification-toasts"
      sx={{
        position: 'fixed',
        top: { xs: 64, sm: 76 },
        right: 12,
        zIndex: 1310,
        display: 'flex',
        flexDirection: 'column',
        gap: 1,
        // The stack itself never blocks the game — only a toast
        // card takes taps, and only inside its own rectangle.
        pointerEvents: 'none',
      }}
    >
      {visible.map(n => (
        <ToastCard key={n.id} notification={n} />
      ))}
    </Box>
  );
};

export default NotificationToasts;
