// @USERNAME — the player's permanent handle (P2.0b). One @name, one
// owner: claimed once, it locks to the account and cannot be changed
// in v1 — the P2.0a database trigger (glacer_pvp_guard) refuses any
// later change server-side, and the unique index on lower(username)
// refuses a second owner. This module is the client half: the format
// rules, the live availability check, and the claim write.
//
// Format (mirrors the database check constraint exactly):
// 3–20 characters, lowercase letters, numbers and underscores only.
// The claim screen lowercases input as it is typed, so a stored name
// is always already lowercase.
import { supabase } from './supabaseClient';

export const USERNAME_PATTERN = /^[a-z0-9_]{3,20}$/;

// What the player typed, normalized the way a stored @name looks:
// trimmed, a leading @ dropped, lowercased.
export function normalizeUsername(raw: string): string {
  return raw.trim().replace(/^@+/, '').toLowerCase();
}

// A plain-language format verdict, or null when the name is well
// formed. Shown live under the claim field.
export function usernameFormatError(name: string): string | null {
  if (name.length === 0) return null;
  if (name.length < 3) return 'At least 3 characters.';
  if (name.length > 20) return 'At most 20 characters.';
  if (!USERNAME_PATTERN.test(name)) {
    return 'Lowercase letters, numbers and underscores only.';
  }
  return null;
}

export function isValidUsername(name: string): boolean {
  return USERNAME_PATTERN.test(name);
}

// Live availability: true when no profile holds this @name. Stored
// usernames are lowercase by constraint, so an exact equality read
// against the column is the unique index's own answer. Throws on a
// network/table error — the caller shows a soft "couldn't check"
// line and the claim write itself stays the final word.
export async function isUsernameAvailable(name: string): Promise<boolean> {
  const { data, error } = await supabase
    .from('profiles')
    .select('id')
    .eq('username', name)
    .limit(1);
  if (error) throw error;
  return (data ?? []).length === 0;
}

// The signed-in player's own claimed @name, or null when they have
// not claimed one yet (or have no profile row yet).
export async function fetchMyUsername(userId: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('profiles')
    .select('username')
    .eq('id', userId)
    .maybeSingle();
  if (error) throw error;
  return (data as { username: string | null } | null)?.username ?? null;
}

export type ClaimResult =
  | { ok: true; username: string }
  | { ok: false; reason: 'taken' | 'locked' | 'invalid' | 'error'; message: string };

const TAKEN_MESSAGE = 'That @name is already taken — try another one.';

// Claim a @name for the signed-in player. The write is an upsert of
// ONLY the username column on the player's own row: a missing row is
// created with the name on it, an unclaimed row gains it, and the
// database itself has the last word on every race — the unique index
// refuses a name another account holds (23505) and the claim-once
// trigger refuses to move a name that is already set (its message
// names the lock). Both refusals come back as plain, friendly lines.
export async function claimUsername(userId: string, rawName: string): Promise<ClaimResult> {
  const name = normalizeUsername(rawName);
  if (!isValidUsername(name)) {
    return {
      ok: false,
      reason: 'invalid',
      message: usernameFormatError(name) ?? 'That @name is not in a valid shape.',
    };
  }
  try {
    const { error } = await supabase
      .from('profiles')
      .upsert({ id: userId, username: name }, { onConflict: 'id' });
    if (!error) return { ok: true, username: name };
    const code = (error as { code?: string }).code;
    const message = error.message ?? '';
    if (code === '23505' || /profiles_username_key|duplicate/i.test(message)) {
      return { ok: false, reason: 'taken', message: TAKEN_MESSAGE };
    }
    if (/username is locked/i.test(message)) {
      return {
        ok: false,
        reason: 'locked',
        message: 'Your @name is already set and locked — it cannot be changed.',
      };
    }
    if (code === '23514' || /profiles_username_shape/i.test(message)) {
      return {
        ok: false,
        reason: 'invalid',
        message: 'Lowercase letters, numbers and underscores only, 3–20 characters.',
      };
    }
    return {
      ok: false,
      reason: 'error',
      message: `Could not claim that @name (${message || 'network error'}).`,
    };
  } catch (err) {
    return {
      ok: false,
      reason: 'error',
      message: `Could not claim that @name (${err instanceof Error ? err.message : 'network error'}).`,
    };
  }
}
