// Profile picture (Round 34, Eddie 2026-11-18) — the player's ONE
// identity picture, shown wherever the player appears (Profile,
// Home greeting, their forum posts, their own message bubbles).
//
// IDENTITY ONLY, by Eddie's standing rule: exactly one picture, no
// gallery, no history, no photo posts anywhere. "That's not us."
//
// Storage: ON-DEVICE ONLY. The picture is a small data URL kept in
// localStorage (`glacer-profile-picture`) — it is never uploaded,
// never sent over the network, never bundled with location, and no
// other player can see, set or change it in this phase. Processing
// shrinks the chosen image to a modest square so it fits
// comfortably in localStorage: max 256×256, and the stored data URL
// is capped at MAX_CHARS (shrinking further if an image is unusually
// dense) — the budget every surface can rely on.
import { useEffect, useState } from 'react';

export const PROFILE_PICTURE_KEY = 'glacer-profile-picture';
export const PROFILE_PICTURE_EVENT = 'glacer-profile-picture-changed';
export const PROFILE_PICTURE_MAX_DIM = 256;
export const PROFILE_PICTURE_MAX_CHARS = 120_000;

export function loadProfilePicture(): string | null {
  try {
    const raw = localStorage.getItem(PROFILE_PICTURE_KEY);
    if (!raw) return null;
    // Only ever a small image data URL we wrote ourselves; anything
    // else in the key is treated as "no picture" rather than trusted.
    if (!raw.startsWith('data:image/') || raw.length > PROFILE_PICTURE_MAX_CHARS) return null;
    return raw;
  } catch {
    return null;
  }
}

function announceProfilePictureChange() {
  try {
    window.dispatchEvent(new Event(PROFILE_PICTURE_EVENT));
  } catch {
    // No window (tests/SSR) — the store still updated.
  }
}

export function saveProfilePicture(dataUrl: string): void {
  try {
    localStorage.setItem(PROFILE_PICTURE_KEY, dataUrl);
  } catch {
    // Storage full/blocked — the picture simply does not persist.
    return;
  }
  announceProfilePictureChange();
}

export function clearProfilePicture(): void {
  try {
    localStorage.removeItem(PROFILE_PICTURE_KEY);
  } catch {
    // Nothing to clear.
  }
  announceProfilePictureChange();
}

// Live view of the stored picture: mounts with the current value and
// updates the moment it is set, changed or removed anywhere in the
// app (same-tab event + cross-tab storage event).
export function useProfilePicture(): string | null {
  const [picture, setPicture] = useState<string | null>(() => loadProfilePicture());
  useEffect(() => {
    const refresh = () => setPicture(loadProfilePicture());
    window.addEventListener(PROFILE_PICTURE_EVENT, refresh);
    window.addEventListener('storage', refresh);
    return () => {
      window.removeEventListener(PROFILE_PICTURE_EVENT, refresh);
      window.removeEventListener('storage', refresh);
    };
  }, []);
  return picture;
}

// Turn a player-picked image file into the stored data URL:
// center-crop to a square, scale down to at most 256×256, encode as
// WebP (JPEG where WebP encoding is unavailable), stepping the size
// down until the result fits the storage budget. Throws on a
// non-image or an image that cannot be decoded.
export async function processProfileImage(file: File): Promise<string> {
  if (!file.type.startsWith('image/')) {
    throw new Error('not-an-image');
  }
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise<HTMLImageElement>((resolve, reject) => {
      const el = new Image();
      el.onload = () => resolve(el);
      el.onerror = () => reject(new Error('image-decode-failed'));
      el.src = url;
    });
    const side = Math.min(img.naturalWidth, img.naturalHeight);
    if (!side) throw new Error('image-decode-failed');
    const sx = (img.naturalWidth - side) / 2;
    const sy = (img.naturalHeight - side) / 2;
    for (const dim of [PROFILE_PICTURE_MAX_DIM, 192, 128, 96]) {
      const canvas = document.createElement('canvas');
      canvas.width = dim;
      canvas.height = dim;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('canvas-unavailable');
      ctx.drawImage(img, sx, sy, side, side, 0, 0, dim, dim);
      let dataUrl = canvas.toDataURL('image/webp', 0.85);
      if (!dataUrl.startsWith('data:image/webp')) {
        // WebP encode unsupported (the canvas fell back to PNG) —
        // JPEG keeps the stored size in budget.
        dataUrl = canvas.toDataURL('image/jpeg', 0.85);
      }
      if (dataUrl.length <= PROFILE_PICTURE_MAX_CHARS) return dataUrl;
    }
    throw new Error('image-too-large');
  } finally {
    URL.revokeObjectURL(url);
  }
}
