// Aspect (w/h parts) of the artwork a URL points at, or null when the
// URL is not a known art asset. Accepts the full public URL the card
// components build (PUBLIC_URL-prefixed, possibly with a query string).
export function artDimensionsForUrl(
  url: string | null | undefined
): readonly [number, number] | null {
  if (!url) return null;
  const clean = url.split('?')[0].split('#')[0];
  const cardsAt = clean.indexOf('/cards/');
  if (cardsAt >= 0) {
    return CARD_ART_DIMENSIONS[clean.slice(cardsAt + '/cards/'.length)] ?? null;
  }
  const navAt = clean.indexOf('/navitars/');
  if (navAt >= 0) {
    return PORTRAIT_ART_DIMENSIONS[clean.slice(navAt + '/navitars/'.length)] ?? null;
  }
  return null;
}
