const BoardView: React.FC<{
  board: ForumBoardId;
  threads: ForumThread[];
  onCreate: (thread: ForumThread) => void;
}> = ({ board, threads, onCreate }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  // Round 15 (Eddie, 2026-11-17): When is picked on a calendar —
  // native date + time inputs, composed on submit into the same
  // human `when` string threads have always carried.
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [where, setWhere] = useState('');
  // Round 15: the location finder. Picking a demo venue fills
  // Where and remembers its id; typing in Where directly is the
  // custom-place path and clears the venue claim. Venues and
  // public places only — never homes or people's locations.
  const [venueId, setVenueId] = useState<string | undefined>(undefined);
  const [placeQuery, setPlaceQuery] = useState('');
  const [finderOpen, setFinderOpen] = useState(false);
  const author = myDisplayName();
  const canPost = title.trim() !== '' && body.trim() !== '';

  const venueMatches = useMemo(() => {
    const q = placeQuery.trim().toLowerCase();
    if (!q) return DEMO_VENUES;
    return DEMO_VENUES.filter(v =>
      `${v.name} ${v.kind} ${v.area} ${v.tagline}`.toLowerCase().includes(q)
    );
  }, [placeQuery]);

  const pickVenue = (venue: (typeof DEMO_VENUES)[number]) => {
    setWhere(`${venue.name} · ${venue.area}`);
    setVenueId(venue.id);
    setPlaceQuery('');
    setFinderOpen(false);
  };

  const editWhere = (value: string) => {
    setWhere(value);
    setVenueId(undefined);
  };

  const whenPreview = date ? formatMeetupWhen(date, time) : '';

  const submit = () => {
    if (!canPost) return;
    onCreate({
      id: newForumId('thread'),
      board,
      title: title.trim(),
      body: body.trim(),
      author,
      createdAt: Date.now(),
      when: whenPreview || undefined,
      where: where.trim() || undefined,
      venueId: where.trim() ? venueId : undefined,
      startsAt: date ? meetupStartsAt(date, time) : undefined,
      replies: [],
    });
    setTitle('');
    setBody('');
    setDate('');
    setTime('');
    setWhere('');
    setVenueId(undefined);
    setPlaceQuery('');
    setFinderOpen(false);
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
      <Button component={RouterLink} to="/forums" sx={{ mb: 2 }}>
        ← All boards
      </Button>
      <Typography variant="h4" gutterBottom>
        {boardName(board)}
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        {FORUM_BOARDS.find(b => b.id === board)?.blurb}
      </Typography>

      {threads.map(thread => (
        <ThreadRow key={thread.id} thread={thread} />
      ))}
      {threads.length === 0 && (
        <Typography color="text.secondary" sx={{ mb: 3 }}>
          No threads yet — start the first one below.
        </Typography>
      )}

      <Paper sx={{ p: 3, mt: 3 }}>
        <Typography variant="h6" gutterBottom>
          Start a thread
        </Typography>
        <TextField
          data-testid="thread-create-title"
          label="Title"
          value={title}
          onChange={e => setTitle(e.target.value)}
          fullWidth
          size="small"
          sx={{ mb: 2 }}
        />
        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 1 }}>
          <TextField
            data-testid="thread-create-date"
            label="Date"
            type="date"
            value={date}
            onChange={e => setDate(e.target.value)}
            size="small"
            InputLabelProps={{ shrink: true }}
            sx={{ flex: '1 1 160px' }}
          />
          <TextField
            data-testid="thread-create-time"
            label="Time"
            type="time"
            value={time}
            onChange={e => setTime(e.target.value)}
            size="small"
            InputLabelProps={{ shrink: true }}
            sx={{ flex: '1 1 120px' }}
          />
        </Box>
        {whenPreview && (
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ mb: 2 }}
            data-testid="thread-create-when-preview"
          >
            🗓️ {whenPreview}
          </Typography>
        )}
        <TextField
          data-testid="thread-create-place-search"
          label="Find a place"
          placeholder="Search bars, parks, beaches…"
          value={placeQuery}
          onChange={e => {
            setPlaceQuery(e.target.value);
            setFinderOpen(true);
          }}
          onFocus={() => setFinderOpen(true)}
          onBlur={() => window.setTimeout(() => setFinderOpen(false), 200)}
          fullWidth
          size="small"
          sx={{ mb: 1 }}
        />
        {finderOpen && (
          <Box data-testid="venue-finder-results" sx={{ mb: 2 }}>
            {venueMatches.map(venue => (
              <Box
                key={venue.id}
                component="button"
                type="button"
                data-testid={`venue-finder-result-${venue.id}`}
                onMouseDown={e => {
                  e.preventDefault();
                  pickVenue(venue);
                }}
                sx={{
                  display: 'block',
                  width: '100%',
                  textAlign: 'left',
                  p: 1.5,
                  mb: 1,
                  borderRadius: 2,
                  border: '1px solid',
                  borderColor: venueId === venue.id ? 'primary.main' : 'divider',
                  bgcolor: 'background.paper',
                  cursor: 'pointer',
                  font: 'inherit',
                  color: 'inherit',
                }}
              >
                <Typography variant="body2">
                  📍 <strong>{venue.name}</strong> · {venue.area}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  {venue.kind} — {venue.tagline}
                </Typography>
              </Box>
            ))}
            {venueMatches.length === 0 && (
              <Typography variant="body2" color="text.secondary">
                No demo place matches that — type any public place in Where below instead.
              </Typography>
            )}
            <Typography variant="caption" color="text.secondary">
              Demo places only in the finder — or type a custom public place in Where.
            </Typography>
          </Box>
        )}
        <TextField
          data-testid="thread-create-where"
          label="Where"
          placeholder="e.g. The Neon Marquee · Hollywood"
          value={where}
          onChange={e => editWhere(e.target.value)}
          fullWidth
          size="small"
          sx={{ mb: 2 }}
        />
        <TextField
          data-testid="thread-create-body"
          label="Details"
          value={body}
          onChange={e => setBody(e.target.value)}
          fullWidth
          multiline
          minRows={3}
          sx={{ mb: 2 }}
        />
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
          <Button
            data-testid="thread-create-submit"
            variant="contained"
            disabled={!canPost}
            onClick={submit}
          >
            Post thread
          </Button>
          <Typography variant="body2" color="text.secondary">
            <Box component="span" sx={authorLineSx}>
              <PlayerAvatar size={16} testId="forum-own-avatar" />
              <span>
                Posting as <strong>{author}</strong>
                {author === 'You' && ' — set your name on the Home page to sign your posts'}
              </span>
            </Box>
          </Typography>
        </Box>
      </Paper>
    </Container>
  );
};

const ThreadView: React.FC<{
  thread: ForumThread;
  onReply: (threadId: string, body: string) => void;
}> = ({ thread, onReply }) => {
  const [reply, setReply] = useState('');
  const author = myDisplayName();
  const canReply = reply.trim() !== '';

  // Moderation (Round 35): a thread is a moderated space. Its
  // owner is its author; the viewer's role follows from that.
  // Demo hosts own their threads (the player is a plain member
  // there and sees badges but no controls); threads the player
  // started expose the full owner toolset.
  const spaceId = forumSpaceId(thread.id);
  const { mod, update } = useSpaceModeration(spaceId);
  const ownerKey = `name:${thread.author}`;
  const viewerKey = `name:${author}`;
  const viewerRole = roleInSpace(mod, ownerKey, viewerKey);
  const viewerCanMod = canModerate(viewerRole);
  const now = () => Date.now();

  const participantKeysInOrder: string[] = [];
  {
    const seen = new Set<string>();
    for (const name of [thread.author, ...thread.replies.map(r => r.author)]) {
      const k = `name:${name}`;
      if (!seen.has(k)) {
        seen.add(k);
        participantKeysInOrder.push(k);
      }
    }
  }
  const participants = activeKeys(mod, participantKeysInOrder).map(k => ({
    key: k,
    label: k.slice('name:'.length),
  }));

  const visibleReplies = thread.replies.filter(r =>
    postRenders(mod, `name:${r.author}`, r.createdAt)
  );
  const flow = mergeFlow(
    visibleReplies.map(r => ({ ...r, ts: r.createdAt })),
    mod.systemLines
  );

  const pinnedItems = mod.pinnedMessages.flatMap(key => {
    if (mod.removedMessages.includes(key)) return [];
    if (key === 'op') return [{ key, authorLabel: thread.author, text: thread.body }];
    const r = thread.replies.find(x => x.id === key);
    if (!r || !postRenders(mod, `name:${r.author}`, r.createdAt)) return [];
    return [{ key, authorLabel: r.author, text: r.body }];
  });

  const submit = () => {
    if (!canReply || mod.locked) return;
    onReply(thread.id, reply.trim());
    setReply('');
  };

  const toggleLock = () => update(setLocked(mod, !mod.locked, 'thread', viewerRole, now()));

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
      <Button component={RouterLink} to={`/forums?board=${thread.board}`} sx={{ mb: 2 }}>
        ← {boardName(thread.board)}
      </Button>
      <Typography variant="h4" gutterBottom>
        {thread.title}
      </Typography>
      {viewerCanMod && (
        <Button
          size="small"
          variant="outlined"
          data-testid="mod-lock-toggle"
          onClick={toggleLock}
          sx={{ mb: 2 }}
        >
          {mod.locked ? '🔓 Unlock thread' : '🔒 Lock thread'}
        </Button>
      )}
      <WhenWhereHeader thread={thread} />
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 1,
          mb: 1,
        }}
      >
        <Typography variant="body2" color="text.secondary">
          <Box component="span" sx={authorLineSx}>
            <OwnAuthorAvatar author={thread.author} />
            <span>
              {thread.author} · {formatWhen(thread.createdAt)}
            </span>
            <RoleBadgeFor mod={mod} ownerKey={ownerKey} participantKey={ownerKey} />
          </Box>
        </Typography>
        {viewerCanMod && (
          <MessageModMenu
            messageKey="op"
            pinned={mod.pinnedMessages.includes('op')}
            onPin={() => update(pinMessage(mod, 'op', viewerRole, now()))}
            onUnpin={() => update(unpinMessage(mod, 'op', viewerRole, now()))}
            onRemove={() => update(removeMessage(mod, 'op', viewerRole, now()))}
          />
        )}
      </Box>
      {mod.removedMessages.includes('op') ? (
        <Typography
          variant="body1"
          color="text.secondary"
          sx={{ mb: 4, fontStyle: 'italic' }}
          data-testid="mod-removed-placeholder"
        >
          {REMOVED_PLACEHOLDER}
        </Typography>
      ) : (
        <Typography variant="body1" sx={{ mb: 4, whiteSpace: 'pre-wrap' }}>
          {thread.body}
        </Typography>
      )}

      <ParticipantsPanel
        mod={mod}
        ownerKey={ownerKey}
        viewerKey={viewerKey}
        participants={participants}
        onAppoint={(key, label) => update(appointModerator(mod, key, label, viewerRole, now()))}
        onUnappoint={(key, label) => update(unappointModerator(mod, key, label, viewerRole, now()))}
        onMute={(key, label) => update(muteParticipant(mod, key, label, viewerRole, now()))}
        onUnmute={(key, label) => update(unmuteParticipant(mod, key, label, viewerRole, now()))}
        onRemove={(key, label) => update(removeParticipant(mod, key, label, viewerRole, now()))}
      />

      <PinnedArea
        items={pinnedItems}
        canMod={viewerCanMod}
        onUnpin={key => update(unpinMessage(mod, key, viewerRole, now()))}
      />

      <Typography variant="h6" gutterBottom>
        {visibleReplies.length} {visibleReplies.length === 1 ? 'reply' : 'replies'}
      </Typography>
      {flow.map(item =>
        item.kind === 'sys' ? (
          <Box key={item.line.id} sx={{ mb: 1.5, display: 'flex', justifyContent: 'center' }}>
            <SystemLineRow line={item.line} />
          </Box>
        ) : (
          <Paper
            key={item.msg.id}
            sx={{ p: 2, mb: 1.5, borderRadius: 3 }}
            data-testid="forum-reply"
          >
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 1,
                mb: 0.5,
              }}
            >
              <Typography variant="body2" color="text.secondary">
                <Box component="span" sx={authorLineSx}>
                  <OwnAuthorAvatar author={item.msg.author} />
                  <span>
                    {item.msg.author} · {formatWhen(item.msg.createdAt)}
                  </span>
                  <RoleBadgeFor
                    mod={mod}
                    ownerKey={ownerKey}
                    participantKey={`name:${item.msg.author}`}
                  />
                </Box>
              </Typography>
              {viewerCanMod && (
                <MessageModMenu
                  messageKey={item.msg.id}
                  pinned={mod.pinnedMessages.includes(item.msg.id)}
                  onPin={() => update(pinMessage(mod, item.msg.id, viewerRole, now()))}
                  onUnpin={() => update(unpinMessage(mod, item.msg.id, viewerRole, now()))}
                  onRemove={() => update(removeMessage(mod, item.msg.id, viewerRole, now()))}
                />
              )}
            </Box>
            {mod.removedMessages.includes(item.msg.id) ? (
              <Typography
                variant="body1"
                color="text.secondary"
                sx={{ fontStyle: 'italic' }}
                data-testid="mod-removed-placeholder"
              >
                {REMOVED_PLACEHOLDER}
              </Typography>
            ) : (
              <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
                {item.msg.body}
              </Typography>
            )}
          </Paper>
        )
      )}

      {mod.locked ? (
        <LockedBanner noun="thread" canMod={viewerCanMod} onUnlock={toggleLock} />
      ) : (
        <Paper sx={{ p: 3, mt: 3 }}>
          <Typography variant="h6" gutterBottom>
            Join the conversation
          </Typography>
          <TextField
            data-testid="reply-input"
            label="Your reply"
            value={reply}
            onChange={e => setReply(e.target.value)}
            fullWidth
            multiline
            minRows={2}
            sx={{ mb: 2 }}
          />
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
            <Button
              data-testid="reply-submit"
              variant="contained"
              disabled={!canReply}
              onClick={submit}
            >
              Post reply
            </Button>
            <Typography variant="body2" color="text.secondary">
              <Box component="span" sx={authorLineSx}>
                <PlayerAvatar size={16} testId="forum-own-avatar" />
                <span>
                  Posting as <strong>{author}</strong>
                </span>
              </Box>
            </Typography>
          </Box>
        </Paper>
      )}
    </Container>
  );
};

const Forums: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [threads, setThreads] = useState<ForumThread[]>(() => loadForums());

  const boardParam = searchParams.get('board') ?? undefined;
  const threadId = searchParams.get('thread');
  const board: ForumBoardId | null = isForumBoardId(boardParam) ? boardParam : null;
  const thread = useMemo(
    () => (threadId ? (threads.find(t => t.id === threadId) ?? null) : null),
    [threads, threadId]
  );

  const createThread = (thread: ForumThread) => {
    setThreads(prev => {
      const next = [...prev, thread];
      saveForums(next);
      return next;
    });
  };

  const addReply = (threadId: string, body: string) => {
    setThreads(prev => {
      const next = prev.map(t =>
        t.id === threadId
          ? {
              ...t,
              replies: [
                ...t.replies,
                { id: newForumId('reply'), author: myDisplayName(), body, createdAt: Date.now() },
              ],
            }
          : t
      );
      saveForums(next);
      return next;
    });
  };

  if (threadId) {
    if (!thread) {
      return (
        <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
          <Typography variant="h4" gutterBottom>
            Thread not found
          </Typography>
          <Typography color="text.secondary" paragraph>
            That conversation is not on this device’s boards.
          </Typography>
          <Button component={RouterLink} to="/forums" variant="contained">
            Back to the Forums
          </Button>
        </Container>
      );
    }
    return <ThreadView thread={thread} onReply={addReply} />;
  }
  if (board) {
    return (
      <BoardView
        board={board}
        threads={threads.filter(t => t.board === board)}
        onCreate={createThread}
      />
    );
  }
  return <ForumsHome threads={threads} />;
};

export default Forums;
