// Legacy storage migration (brand rename, Eddie 2026-11-14: the app
// is GLACER; "icewall" is retired). Every localStorage key was
// renamed icewall-* -> glacer-*. This shim runs once at app start —
// before any context reads storage — and moves each legacy value to
// its new key, then removes the legacy key, so existing demo state
// (collections, potions, titles, presence settings, owner mode) on a
// player's device survives the rename untouched. If BOTH keys exist
// the new key wins (it is the fresher write) and the legacy key is
// still removed, so the migration never runs twice on stale data.
const LEGACY_KEY_PAIRS: ReadonlyArray<readonly [string, string]> = [
  ['icewall-active-navitar-id', 'glacer-active-navitar-id'],
  ['icewall-avatar-outfit', 'glacer-avatar-outfit'],
  ['icewall-checked-in-venue', 'glacer-checked-in-venue'],
  ['icewall-companion-marker', 'glacer-companion-marker'],
  ['icewall-display-name', 'glacer-display-name'],
  ['icewall-friends', 'glacer-friends'],
  ['icewall-joe-marker', 'glacer-joe-marker'],
  ['icewall-live-ai', 'glacer-live-ai'],
  ['icewall-owner-flag', 'glacer-owner-flag'],
  ['icewall-owner-mode', 'glacer-owner-mode'],
  ['icewall-pending-challenge', 'glacer-pending-challenge'],
  ['icewall-points', 'glacer-points'],
  ['icewall-portal-marker', 'glacer-portal-marker'],
  ['icewall-potions', 'glacer-potions'],
  ['icewall-power-boost', 'glacer-power-boost'],
  ['icewall-station-cooldowns', 'glacer-station-cooldowns'],
  ['icewall-station-marker', 'glacer-station-marker'],
  ['icewall-stroll-walk-as', 'glacer-stroll-walk-as'],
  ['icewall-threads', 'glacer-threads'],
  ['icewall-titles', 'glacer-titles'],
  ['icewall-training', 'glacer-training'],
  ['icewall-user-navitar', 'glacer-user-navitar'],
  ['icewall-user-navitars', 'glacer-user-navitars'],
  ['icewall-venue-marker', 'glacer-venue-marker'],
  ['icewall-venue-wins', 'glacer-venue-wins'],
  ['icewall-wild-marker', 'glacer-wild-marker'],
  ['icewall-win-streak', 'glacer-win-streak'],
  ['icewall-wl-record', 'glacer-wl-record'],
  ['icewall-you-marker', 'glacer-you-marker'],
];

export function migrateLegacyStorageKeys(): void {
  try {
    for (const [legacyKey, newKey] of LEGACY_KEY_PAIRS) {
      const legacyValue = window.localStorage.getItem(legacyKey);
      if (legacyValue === null) continue;
      if (window.localStorage.getItem(newKey) === null) {
        window.localStorage.setItem(newKey, legacyValue);
      }
      window.localStorage.removeItem(legacyKey);
    }
  } catch {
    // Storage unavailable (private mode, quotas): the app already
    // treats every read defensively; a failed migration must never
    // block boot.
  }
}
