export function getCollectibleCard(name: string | null | undefined): string | null {
  if (!name) return null;
  return COLLECTIBLE_CARDS[name.trim().toLowerCase()] ?? null;
}

export const COLLECTIBLE_CARD_COUNT = Object.keys(COLLECTIBLE_CARDS).length;
