import React, { useEffect, useMemo, useRef, useState } from 'react';
import { fxColors } from '../utils/attackFx';
import { AMBIENT_LOAD_SLOWDOWN, useAnyModelLoading } from '../utils/modelLoading';

// Elemental ambience (Navidex ambient animation, Eddie 2026-11-16):
// the dripping / drifting elemental background behind a navitar,
// in the SAME palette as the battle attack FX (utils/attackFx.ts
// ELEMENT_FX via fxColors), so the Navidex and Battle read as one
// world. Pure CSS particles — capped counts (stage 22, card 10,
// both under the ≤40-per-effect law), no canvas, no extra assets.
//
// Per element (spec: navidex-ambient-animation-spec.md):
//   ice      — melt drips falling + frost motes
//   fire     — embers rising + slow lava drips
//   water    — drips falling
//   electric — sparks crackling down, fast and short
//   nature   — leaves / pollen drifting down with a sway
//   shadow   — dark violet wisps sinking
//   light    — light motes floating slowly
//   quantum  — prismatic droplets (hue-cycling drips)
//   spiritual— teal-gold wisps drifting
//
// Motion law: this is presentation motion only. It runs only while
// the surface is on screen and the tab is visible (useAmbientActive
// for the Stage), and prefers-reduced-motion kills it entirely in
// CSS — the real app has no separate Smooth toggle (the prototype
// did), so the OS setting + visibility/intersection pausing is the
// mechanism; nothing conflicting was invented.

export function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(
    () =>
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
  useEffect(() => {
    if (typeof window.matchMedia !== 'function') return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener?.('change', onChange);
    return () => mq.removeEventListener?.('change', onChange);
  }, []);
  return reduced;
}

// True only while the referenced element is intersecting the
// viewport, the document is visible, and the user has not asked
// for reduced motion. The Stage's ambient loop (idle sway, drips,
// energy shots) gates on this.
export function useAmbientActive(ref: React.RefObject<Element | null>): boolean {
  const reduced = usePrefersReducedMotion();
  const [onScreen, setOnScreen] = useState(true);
  const [docVisible, setDocVisible] = useState(
    () => typeof document === 'undefined' || document.visibilityState !== 'hidden'
  );

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === 'undefined') return;
    const obs = new IntersectionObserver(
      entries => setOnScreen(entries[0]?.isIntersecting ?? true),
      {
        threshold: 0.15,
      }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [ref]);

  useEffect(() => {
    const onVis = () => setDocVisible(document.visibilityState !== 'hidden');
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);

  return !reduced && onScreen && docVisible;
}

// Deterministic per-seed pseudo-random in [0,1): the same navitar
// always gets the same particle field, and different navitars are
// offset from each other — a screen of fighters never pulses in sync.
function rand(seed: string, i: number): number {
  let h = 2166136261;
  const s = `${seed}:${i}`;
  for (let k = 0; k < s.length; k++) {
    h ^= s.charCodeAt(k);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}

type ParticleMode = 'fall' | 'rise' | 'float';

const ELEMENT_MODE: Record<string, ParticleMode> = {
  fire: 'rise',
  light: 'float',
  spiritual: 'float',
};

const ElementalAmbience: React.FC<{
  element: string;
  seed: string;
  variant?: 'stage' | 'card';
  // Stage passes its useAmbientActive result; cards rely on CSS
  // (reduced-motion kill + cheap transform/opacity particles).
  active?: boolean;
}> = ({ element, seed, variant = 'stage', active = true }) => {
  const colors = fxColors(element);
  const el = (element || '').toLowerCase();
  const count = variant === 'stage' ? 22 : 10;
  const mode = ELEMENT_MODE[el] ?? 'fall';
  // Round 24 (Eddie approved): while a 3D model is loading anywhere
  // (utils/modelLoading), the background ambience eases off — every
  // particle's duration stretches by AMBIENT_LOAD_SLOWDOWN — and
  // resumes its normal rate when the last load lands. The state is
  // mirrored on the container (data-amb-slowed / data-amb-rate) so
  // the slowdown is observable, not just felt.
  const loadSlowed = useAnyModelLoading();
  const rate = loadSlowed ? 1 / AMBIENT_LOAD_SLOWDOWN : 1;

  const particles = useMemo(
    () =>
      Array.from({ length: count }, (_, i) => {
        const r1 = rand(seed, i * 4);
        const r2 = rand(seed, i * 4 + 1);
        const r3 = rand(seed, i * 4 + 2);
        const r4 = rand(seed, i * 4 + 3);
        return {
          key: i,
          left: `${(r1 * 96 + 2).toFixed(1)}%`,
          size: variant === 'stage' ? 3 + r2 * 5 : 2 + r2 * 4,
          duration: ((mode === 'fall' ? 3.4 : 5.5) + r3 * 4) / rate,
          delay: -r4 * 8,
          drift: `${(r2 - 0.5) * 36}px`,
          // Quantum runs prismatic: particles cycle hue as they fall.
          color:
            el === 'quantum'
              ? `hsl(${Math.floor(r3 * 360)}, 90%, 74%)`
              : i % 3 === 0
                ? colors.secondary
                : colors.primary,
          elongated: mode === 'fall' && el !== 'nature' && el !== 'shadow',
          blurred: el === 'shadow' || el === 'spiritual',
        };
      }),
    [count, seed, mode, el, colors.primary, colors.secondary, variant, rate]
  );

  if (!active) return null;

  return (
    <div
      className={`glacer-amb glacer-amb-${variant}`}
      aria-hidden
      data-amb-slowed={loadSlowed ? 'true' : undefined}
      data-amb-rate={rate.toFixed(2)}
    >
      {particles.map(p => (
        <span
          key={p.key}
          className={`glacer-amb-p glacer-amb-${mode}`}
          style={
            {
              left: p.left,
              width: p.elongated ? Math.max(2, p.size * 0.45) : p.size,
              height: p.elongated ? p.size * 2.6 : p.size,
              background: p.color,
              boxShadow: `0 0 ${p.size * 2}px ${p.color}`,
              filter: p.blurred ? 'blur(2px)' : undefined,
              opacity: 0.75,
              animationDuration: `${p.duration.toFixed(2)}s`,
              animationDelay: `${p.delay.toFixed(2)}s`,
              '--amb-drift': p.drift,
            } as React.CSSProperties
          }
        />
      ))}
      {/* Frost creep / ember glow wash in the element's own colour. */}
      <div
        className="glacer-amb-wash"
        style={{
          background: `radial-gradient(120% 90% at 50% 100%, ${colors.primary}30, transparent 65%)`,
        }}
      />
    </div>
  );
};

export default ElementalAmbience;
